window.kbPageData["views/entry/k-674d0d2d425c06f1"] = {"key":"entry/k-674d0d2d425c06f1","state":{"route":"entry/k-674d0d2d425c06f1"},"node":{"id":"k-674d0d2d425c06f1","mode":"k","title":"工业固体废物委托处置的受托方核验与书面合同","type":"制度与规则","domain":"生态环境","reading":"","intro":"","priority":100,"aliases":["工业固体废物委托处置的资质核验与合同约定"],"qs":["国考 2025 行政执法 申论#4"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"按2024年考试时适用的规定，产生工业固体废物的单位委托他人运输、利用或处置工业固体废物，应核实受托方的主体资格和技术能力，依法签订书面合同并约定污染防治要求。委托经营性收集、贮存、利用或处置危险废物时，受托方须持有相应的危险废物经营许可证，并按许可范围开展活动。","review":{"definition":"按2024年考试时适用的规定，产生工业固体废物的单位委托他人运输、利用或处置工业固体废物，应核实受托方的主体资格和技术能力，依法签订书面合同并约定污染防治要求。委托经营性收集、贮存、利用或处置危险废物时，受托方须持有相应的危险废物经营许可证，并按许可范围开展活动。","explanation":"西瑞药业核实专业处置单位资质、签订书面合同并约定污染防治要求，可作为谈话提纲中的委托处置成效。材料所报100%安全处理率的统计口径是工业固体废物，提纲应沿用这一口径。","references":[{"source":"web-500595e3e43719b7","location":"第三十七条第一款、第八十条","quote":"对受托方的主体资格和技术能力进行核实"}],"evidence":"对方的资质，依法签订书面合同，约定污染防治要求","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"questions":{"国考 2025 行政执法 申论#4":{"paper":"国考 2025 行政执法 申论","n":4,"mod":"申论","src":["dbb2469ea58338709f40.pdf",4],"asrc":["d1fc3fe21ef6ae3b1ae6.pdf",3],"card":"e9b26cf35f72426e9b032d20","links":[{"id":"k-674d0d2d425c06f1","role":"直接考查","why":"核验受托方资质、签订书面合同并约定污染防治要求是评价委托处置成效的依据。"}]}},"terms":{},"references":{"web-500595e3e43719b7":{"name":"中华人民共和国固体废物污染环境防治法（2020年修订）","url":"https://www.miit.gov.cn/jgsj/zfs/fl/art/2022/art_f2d9c145e29e4c93a442c8663c2c32ff.html"}},"topics":[],"units":{"k-674d0d2d425c06f1":[["国考 2025 行政执法 申论#4"]]}};
